        const day = row.fecha_pago;

        frappe.call({
            method: "erpnext.setup.utils.get_exchange_rate",
            args: {
                from_currency: 'USD',
                to_currency: row.divisa_de_cambio,
                transaction_date: day,
            },
            callback: (r) => {
                let tasa_de_cambio = redondeo2(r.message, 9);
                row.tasa_de_cambio = tasa_de_cambio;
                refresh_field(row);
            },
        });

        row.cuenta_de_ingreso = '';
        calcularImporteYActualizarTotalNeto(frm, row);
    },

    cantidad(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        calcularImporteYActualizarTotalNeto(frm, row);
    },

    tasa_de_cambio(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        calcularImporteYActualizarTotalNeto(frm, row);
    },
});

