// Función para calcular importe y actualizar el total neto
function calcularImporteYActualizarTotalNeto(frm, row) {
    let cantidad = row.cantidad;
    let tasa = row.tasa_de_cambio;

    if (tasa !== 0) {
        let importe = redondeo2(cantidad / tasa);
        row.importe = importe;
        refresh_field(row);
        
        // Actualizar total neto
        let items = frm.doc.items;
        let total = items.reduce((acc, item) => acc + item.importe, 0);
        frm.set_value("total_neto", total);

        if (frm.doc.comision_cobrada === 0 && frm.doc.comision_pagada === 0) {
            frm.set_value("total_pagar", total);
        }
    }
}

// Función para calcular importe y actualizar el total pagado
function calcularImporteYActualizarTotalPagado(frm, row) {
    let cantidad = row.importe_pagado;
    let tasa = row.tasa_de_pago;

    if (tasa !== 0) {
        let importe = redondeo2(cantidad / tasa);
        row.importe_pago = importe;
        refresh_field(row);

        // Actualizar total pagado
        let pagos = frm.doc.pagos;
        let total = pagos.reduce((acc, pago) => acc + pago.importe_pago, 0);
        frm.set_value("total_pagado", total);
    }
}

